package com.asmj.marketplace.post.service; import com.asmj.marketplace.post.model.Post;import com.asmj.marketplace.post.dto.PostRequest;import com.asmj.marketplace.post.repository.PostRepository;import com.asmj.marketplace.vendor.repository.VendorRepository;import com.asmj.marketplace.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*; @Service @RequiredArgsConstructor public class PostService {private final PostRepository repo;private final VendorRepository vendors;private final UserRepository users;private String uid(String email){return users.findByEmailIgnoreCase(email).orElseThrow().getId();}public Post create(String email,PostRequest r){String uid=uid(email);VendorCheck(uid);Post p=Post.builder().vendorId(vendors.findByUserId(uid).orElseThrow().getId()).categoryId(r.categoryId()).type(r.type().toUpperCase()).title(r.title()).slug(slug(r.title())).description(r.description()).price(r.price()).priceType(r.priceType()).images(r.images()==null?new ArrayList<>():r.images()).attachments(r.attachments()==null?new ArrayList<>():r.attachments()).location(r.location()).attributes(r.attributes()==null?new HashMap<>():r.attributes()).status(Post.PostStatus.DRAFT).approvalStatus(Post.PostStatus.DRAFT).featured(false).createdAt(Instant.now()).updatedAt(Instant.now()).build();return repo.save(p);}private void VendorCheck(String uid){var v=vendors.findByUserId(uid).orElseThrow(()->new IllegalArgumentException("Vendor profile required"));if(v.getVerificationStatus()!=com.asmj.marketplace.vendor.model.Vendor.VerificationStatus.APPROVED)throw new IllegalArgumentException("Vendor is not approved");}private String slug(String s){return s.toLowerCase().replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","")+"-"+UUID.randomUUID().toString().substring(0,6);}public List<Post> all(){return all(null);}public List<Post> all(String type){return type==null||type.isBlank()?repo.findByStatus(Post.PostStatus.PUBLISHED):repo.findByTypeAndStatus(type.toUpperCase(),Post.PostStatus.PUBLISHED);}public List<Post> search(String q){return search(q,null);}public List<Post> search(String q,String type){return type==null||type.isBlank()?repo.search(q):repo.searchByType(q,type.toUpperCase());}public Post get(String id){Post p=repo.findById(id).orElseThrow();if(p.getStatus()==Post.PostStatus.PUBLISHED)p.setViews(p.getViews()+1);return repo.save(p);}public Post preview(String id){return repo.findById(id).orElseThrow();}public List<Post> mine(String email){String uid=uid(email);return repo.findByVendorId(vendors.findByUserId(uid).orElseThrow().getId());}public Post update(String email,String id,PostRequest r){Post p=getMine(email,id);p.setCategoryId(r.categoryId());p.setType(r.type().toUpperCase());p.setTitle(r.title());p.setDescription(r.description());p.setPrice(r.price());p.setPriceType(r.priceType());p.setImages(r.images()==null?new ArrayList<>():r.images());p.setAttachments(r.attachments()==null?new ArrayList<>():r.attachments());p.setLocation(r.location());p.setAttributes(r.attributes());p.setStatus(Post.PostStatus.DRAFT);p.setApprovalStatus(Post.PostStatus.DRAFT);p.setUpdatedAt(Instant.now());return repo.save(p);}public void delete(String email,String id){Post p=getMine(email,id);repo.delete(p);}
public Post submit(String email,String id){Post p=getMine(email,id);p.setStatus(Post.PostStatus.PENDING_APPROVAL);p.setApprovalStatus(Post.PostStatus.PENDING_APPROVAL);return repo.save(p);}private Post getMine(String email,String id){Post p=repo.findById(id).orElseThrow();String vid=vendors.findByUserId(uid(email)).orElseThrow().getId();if(!vid.equals(p.getVendorId()))throw new IllegalArgumentException("Not your listing");return p;}public List<Post> pending(){return repo.findByStatus(Post.PostStatus.PENDING_APPROVAL);}public Post approve(String id,boolean ok){Post p=repo.findById(id).orElseThrow();p.setApprovalStatus(ok?Post.PostStatus.APPROVED:Post.PostStatus.REJECTED);p.setStatus(ok?Post.PostStatus.PUBLISHED:Post.PostStatus.REJECTED);return repo.save(p);}}
